=== FILE: credit_counter_formal.sv ===
// Formal harness and properties for credit_counter (task prj-4986bc98bc:assertions-formal).
// Properties are written from interface_spec.md; each names the rule it checks.
// Immediate assertions in clocked blocks only (open Yosys front end subset).

module credit_counter_props #(
    parameter integer MAX = 4
) (
    input wire clk,
    input wire rst_n,
    input wire take,
    input wire give
);
    localparam [7:0] F_MAX = MAX;

    wire [7:0] credits;
    wire       avail;
    wire       full;
    wire       err;

    credit_counter #(.MAX(MAX)) dut (
        .clk(clk),
        .rst_n(rst_n),
        .take(take),
        .give(give),
        .credits(credits),
        .avail(avail),
        .full(full),
        .err(err)
    );

    // First-cycle guard for $past.
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk)
        f_past_valid <= 1'b1;

    // Only environment assumption: the block is reset in the first cycle,
    // the point from which the specification defines its behaviour.
    always @(*)
        if (!f_past_valid)
            assume(!rst_n);

    // [req:CC-STATUS] avail and full follow credits with no clock edge.
    always @(*) begin
        assert(avail == (credits != 8'd0));
        assert(full == (credits == F_MAX));
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            // [req:CC-RANGE] never above MAX (and, being unsigned, never wrapped below zero).
            assert(credits <= F_MAX);

            if (!$past(rst_n)) begin
                // [req:CC-RESET] reset loads MAX and clears err.
                assert(credits == F_MAX);
                assert(!err);
            end else begin
                if ($past(take) && !$past(give)) begin
                    if ($past(credits) != 8'd0) begin
                        // [req:CC-TAKE] one credit spent; no refusal, err unchanged.
                        assert(credits == $past(credits) - 8'd1);
                        assert(err == $past(err));
                    end else begin
                        // [req:CC-UNDERFLOW] refused take: credits stays zero, err set.
                        assert(credits == 8'd0);
                        assert(err);
                    end
                end

                if ($past(give) && !$past(take)) begin
                    if ($past(credits) != F_MAX) begin
                        // [req:CC-GIVE] one credit returned; no refusal, err unchanged.
                        assert(credits == $past(credits) + 8'd1);
                        assert(err == $past(err));
                    end else begin
                        // [req:CC-OVERFLOW] refused give: credits stays MAX, err set.
                        assert(credits == F_MAX);
                        assert(err);
                    end
                end

                if ($past(take) && $past(give)) begin
                    // [req:CC-BOTH] no change, at zero and at MAX too, nothing refused.
                    assert(credits == $past(credits));
                    assert(err == $past(err));
                end

                if (!$past(take) && !$past(give)) begin
                    // [req:CC-IDLE] no change.
                    assert(credits == $past(credits));
                    assert(err == $past(err));
                end

                if ($past(err)) begin
                    // [req:CC-ERR-STICKY] err stays high until reset.
                    assert(err);
                end
            end
        end
    end

    // Scenario covers the proof must still allow (vacuity check).
    always @(posedge clk) begin
        if (f_past_valid) begin
            // Empty reached.
            cover(credits == 8'd0 && !avail);
            // Full reached again by a give from MAX-1.
            cover($past(rst_n) && $past(give) && !$past(take)
                  && $past(credits) == F_MAX - 8'd1 && full);
            // Underflow refusal.
            cover($past(rst_n) && $past(take) && !$past(give)
                  && $past(credits) == 8'd0 && err);
            // Overflow refusal.
            cover($past(rst_n) && $past(give) && !$past(take)
                  && $past(credits) == F_MAX && err);
            // Take and give together at zero and at MAX.
            cover($past(rst_n) && $past(take) && $past(give) && $past(credits) == 8'd0);
            cover($past(rst_n) && $past(take) && $past(give) && $past(credits) == F_MAX);
            // Reset clears a set err.
            cover(!$past(rst_n) && $past(err) && !err);
        end
    end
endmodule

module credit_counter_formal (
    input wire clk,
    input wire rst_n_a,
    input wire take_a,
    input wire give_a,
    input wire rst_n_b,
    input wire take_b,
    input wire give_b,
    input wire rst_n_c,
    input wire take_c,
    input wire give_c
);
    // [req:CC-PARAM] minimum MAX, the default MAX, and a MAX that is not a power of two.
    credit_counter_props #(.MAX(1)) u_max1 (
        .clk(clk), .rst_n(rst_n_a), .take(take_a), .give(give_a)
    );
    credit_counter_props #(.MAX(4)) u_max4 (
        .clk(clk), .rst_n(rst_n_b), .take(take_b), .give(give_b)
    );
    credit_counter_props #(.MAX(5)) u_max5 (
        .clk(clk), .rst_n(rst_n_c), .take(take_c), .give(give_c)
    );
endmodule
=== END FILE ===
